  insert into public.brands (name, website, description, country, status) values ('Color Me Beautiful', 'https://colormebeautiful.com', 'Heritage color-analysis beauty brand selling makeup and skincare organized by seasonal color palettes; its own affiliate program page states 25% commission on all affiliate sales and ''no limit to what you can earn.''', null, 'published') returning id into bid;
