  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 25, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://colormebeautiful.com/pages/affiliate_program.', 'https://colormebeautiful.com/pages/affiliate_program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Color Me Beautiful Affiliate Program', 'https://colormebeautiful.com/pages/affiliate_program', 'https://colormebeautiful.com/pages/affiliate_program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://colormebeautiful.com/pages/affiliate_program', 'official_site', 'affiliate', 'Color Me Beautiful''s own affiliate program page states: ''25% commission on all affiliate sales (top of the industry), no limit to what you can earn'', plus exclusive product sneak peeks and potential gifted PR/product that affiliates can request in the sign-up form. Joining is a 4-step interest-form process: join, get approved by the CMB or Flori Roberts team, start promoting with a unique URL and creative assets, earn on every qualified purchase. The ''no limit to what you can earn'' statement on the program page itself makes the earnings cap verified uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://colormebeautiful.com/en-au/blogs/colormenow/how-to-join-color-me-beautifuls-affiliate-program-why-you-should-color-me-beautiful', 'official_site', 'affiliate', 'The brand''s own blog guide repeats the terms: ''25% Commission on All Sales'' and ''No Earnings Cap: There''s no ceiling on your potential. The more you promote, the more you can earn.'' It also states no huge following is needed, and gives the brand''s credibility history: Color Me Beautiful has helped over 26 million women, popularized color analysis with its book of the same name plus six additional books, and sells through Seasonal Boutiques organized by palette.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://colormebeautiful.com/pages/affiliate_program', 'official_site', 'creator_saturation', 'No hard absolute creator count for Color Me Beautiful surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 20, 11, 9, 5, '{"niche_fit": "Color-season makeup and skincare is built for try-on and palette-reveal UGC, and the program also covers sister brand Flori Roberts.", "ugc_evidence": "Own-site affiliate program with unique URLs, creative assets, sneak peeks and gifted-product requests inside the sign-up form; no hard creator count published.", "compensation": "25% on all sales with ''no limit to what you can earn'' stated on the program page itself - the strongest verified-uncapped rate in this round.", "contact_access": "Interest form on the brand''s own program page; no public partnerships email was published on the pages fetched.", "opportunity_availability": "Applications open via the interest form with team review; the brand says no huge following is required.", "credibility": "Decades-old color-analysis authority claiming 26 million women helped and seven published books on color and makeup."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('CLEARSTEM', 'https://clearstem.com', 'Skincare brand targeting acne and aging at the same time with ingredient-transparent formulas; its Ambassador affiliate route runs on Impact, and the brand''s own Terms of Service state there is no cap on the total commissions an Ambassador can earn from each order.', 'United States', 'published') returning id into bid;
