  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://clearstem.com/policies/terms-of-service.', 'https://clearstem.com/pages/brand-ambassadors', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'CLEARSTEM Ambassador / Affiliate Program (Impact)', 'https://clearstem.com/pages/brand-ambassadors', 'https://clearstem.com/policies/terms-of-service', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://clearstem.com/policies/terms-of-service', 'official_site', 'affiliate', 'CLEARSTEM''s own Terms of Service (last update August 3, 2026), in the Ambassador obligations section, state: ''Ambassadors earn a commission on each order placed by consumers directed to CLEARSTEM Skincare Inc. by an Ambassador affiliate link...'' and ''there is no cap on the total commissions an Ambassador can earn from each order attributed to their promotions.'' The earnings-cap statement is therefore recorded as uncapped on the brand''s own legal terms, quoted exactly; note the wording is framed per order attributed to the Ambassador''s promotions.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliategraph.ai/programs/clearstem', 'affiliate_directory', 'affiliate', 'AffiliateGraph''s network-listing summary (updated Nov 9, 2026) lists CLEARSTEM on Impact as the direct network (Digidip and Skimlinks as sub-affiliates), with a listed commission range of 3%-25% and a stated base of 20% on online sales, while other directories list 10% (CompareEPC, LinkClicky). Because the published rates conflict across sources, commission_rate is recorded as null rather than settled.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://clearstem.com/policies/terms-of-service', 'official_site', 'creator_saturation', 'No hard absolute creator count for CLEARSTEM surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 14, 10, 8, 5, '{"niche_fit": "Acne-plus-aging positioning with ingredient transparency is proven skincare-UGC material with strong before/after potential.", "ugc_evidence": "A formal Ambassador structure in the brand''s own terms plus a direct Impact network listing; no hard creator count published.", "compensation": "Earnings cap is verified uncapped in the brand''s own Terms, but the percentage conflicts across network listings (3%-25% range, 20% base, 10% elsewhere), so the rate is honestly null.", "contact_access": "Ambassador page referenced in the brand''s own Terms and application through Impact; no public partnerships email on the pages fetched.", "opportunity_availability": "Ambassador obligations are set by a Partnerships Manager per the Terms, so entry is managed rather than instant.", "credibility": "Established DTC skincare brand founded in 2017 by an acne specialist and a holistic nutritionist, per its Sovrn merchant profile."}'::jsonb);
