  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://skinrnr.com/pages/join', 'official_site', 'affiliate', 'Skin RnR''s own Join page publishes its Referral Partner Program: ''Earn 30% Commission - Share your personal referral link and earn 30% when someone places an order through it'', no inventory to manage, support with messaging and product details, and ''There are no quotas.'' Applications are reviewed personally. The page publishes no earnings-cap statement, so commission_cap is recorded as unknown, never guessed.', 'verified', now());
