  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Solid Actives Partner Program', 'https://www.solidactives.com/affiliate/', 'https://www.solidactives.com/affiliate/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.solidactives.com/affiliate/', 'official_site', 'affiliate', 'Solid Actives'' own Partner Program page states partners earn ''20% Commission Earned'' with ''10% Off for Your Audience'', worked example included ($89 order - 10% code = $80.10 paid, 20% = $16.02 commission). It explicitly recruits ''Beauty & Wellness Creators'' alongside aestheticians and editorial platforms, reviews applications personally within 3-5 business days, and activates a custom promo code on approval. The page publishes no earnings-cap statement, so commission_cap is recorded as unknown, never guessed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.solidactives.com/affiliate/', 'official_site', 'creator_saturation', 'The brand says it curates its partner network carefully, but publishes no absolute creator count, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 17, 10, 7, 3, '{"niche_fit": "Premium solid-format actives are distinctive, demo-friendly skincare content for beauty and wellness creators.", "ugc_evidence": "Own-site partner program explicitly recruiting beauty and wellness creators with a worked commission example; no hard creator count published.", "compensation": "20% on the post-discount paid amount is strong; no cap statement is published, so the cap is honestly unknown.", "contact_access": "Application on the brand''s own partner page with personal review in 3-5 business days; no public email on the page fetched.", "opportunity_availability": "Curated approval against stated partnership standards (aesthetic alignment, accurate representation), so entry is selective.", "credibility": "Small premium brand with a detailed, transparent program page; limited third-party footprint."}'::jsonb);
