  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BK Beauty Affiliate Program (ShareASale / Awin)', 'https://ui.awin.com/merchant-profile/91511', 'https://ui.awin.com/merchant-profile/91511', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/91511', 'affiliate_network', 'affiliate', 'BK Beauty''s Awin merchant profile states: ''Our affiliate program offers 15% commission on all sales and our online store has a +$100 average order value'', and describes BK Beauty as a direct-to-consumer cosmetics brand built and fueled by YouTube content creators and influencers. LinkClicky''s directory independently lists the program on ShareASale at 15% per sale with a 30-day cookie. No earnings-cap statement was found on the pages fetched, so commission_cap is recorded as unknown, never guessed.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.digitalcommerce360.com/2021/09/29/in-pursuit-of-maximum-marketing-returns/', 'news', 'affiliate', 'Digital Commerce 360 reported BK Beauty''s affiliate program at 15% commission per product sold via a creator''s link and that the program drove about 30% of the brand''s sales, corroborating both the rate and the program''s centrality. A separate founder interview states direct ShareASale sign-ups receive the full 15% while sub-affiliate networks take a cut.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/91511', 'affiliate_network', 'creator_saturation', 'A founder interview mentioned working with ''over 100 folks'' in the program in 2022, but that figure is dated and not a current hard count, so creator saturation is recorded as unknown rather than low.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 16, 11, 9, 4, '{"niche_fit": "Brushes and makeup from a creator-founded brand are native tutorial and review UGC material.", "ugc_evidence": "Affiliate-led brand from launch: program on ShareASale and Awin, reported at roughly 30% of brand sales, with product seeding described by the founder.", "compensation": "15% on all sales against a +$100 average order value is solid per-sale economics; cap is honestly unknown.", "contact_access": "Joinable through the Awin merchant profile and ShareASale; no public partnerships email on the pages fetched.", "opportunity_availability": "Open network application on two major networks.", "credibility": "Established DTC cosmetics brand with trade-press coverage of its affiliate-led growth."}'::jsonb);
