  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'L''Avyanna Beauty Affiliate Programme', 'https://lavyanna.com/affiliate-programme/', 'https://lavyanna.com/affiliate-programme/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lavyanna.com/affiliate-programme/', 'official_site', 'affiliate', 'L''Avyanna''s own Affiliate Programme page states joining the affiliate program is free via the on-page form: affiliates share a unique link, give customers a 5% discount, and ''receive a commission ranging from 7.5% to 15% based on your engagement strength'' - Category 1 Beauty Enthusiasts earn 7.5% and Category 2 Influencer Affiliates earn 15%, with dashboard access, marketing materials and, for influencers, priority support and collaboration opportunities. The page also lists info@lavyanna.com for its distributor route. Its ''unlimited opportunities'' headline refers to the distributor packages, not an earnings-cap statement, so commission_cap is recorded as unknown, never guessed. The recorded rate is the 7.5% floor.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lavyanna.com/affiliate-programme/', 'official_site', 'creator_saturation', 'No hard absolute creator count for L''Avyanna surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 12, 13, 8, 3, '{"niche_fit": "Science-led skincare formulated for melanin-rich skin is a clear, underserved UGC niche with strong routine content potential.", "ugc_evidence": "Own-site affiliate programme with two creator tiers, dashboard, personalized links and marketing materials; no hard creator count published.", "compensation": "7.5% entry tier rising to 15% for influencer affiliates is modest; cap is honestly unknown - the page''s ''unlimited'' wording is about distributor opportunity, not earnings.", "contact_access": "Published brand email (info@lavyanna.com) plus the free on-page affiliate form.", "opportunity_availability": "Free to join with a basic tier requiring only an active social account or blog.", "credibility": "Niche specialist brand with a detailed programme page; limited third-party footprint, and its paid distributor/stockist packages sit alongside the free affiliate route."}'::jsonb);
