  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Rejuvaform Brand Ambassador Program', 'https://www.rejuvaform.com/pages/brand-ambassador-program', 'https://www.rejuvaform.com/pages/brand-ambassador-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.rejuvaform.com/pages/brand-ambassador-program', 'official_site', 'affiliate', 'Rejuvaform''s own Brand Ambassador Program page states: ''15% commission paid monthly on all Rejuvaform products'', 20% off for ambassadors, a 10% follower discount via the affiliate code, free products customized to skin requirements, and early access. Approved ambassadors receive a free product package and must post testimonials and content at least monthly. The page says the program is ''Currently open to Canadian residents only'' while its ideal-ambassador list mentions Canada and the Continental US - that inconsistency is recorded here rather than smoothed over. The page publishes no earnings-cap statement, so commission_cap is recorded as unknown, never guessed.', 'verified', now());
