  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 16, 13, 6, 3, '{"niche_fit": "Personalized Dry+ plant-based skincare with free tailored product is natural testimonial and routine UGC.", "ugc_evidence": "Own-site ambassador program with free product packages, monthly content requirements and featured-ambassador placements; no hard creator count published.", "compensation": "15% monthly commission on all products plus free product and a 20% personal discount; cap is honestly unknown.", "contact_access": "Published email (hello@rejuvaform.com) plus the application form linked from the program page.", "opportunity_availability": "Applications open but the page currently limits the program to Canadian residents, which narrows creator eligibility.", "credibility": "Made-in-Canada, vegan and cruelty-free positioning stated on the page; small brand with limited third-party footprint."}'::jsonb);
