  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ora''s Amazing Herbal Brand Ambassador / Shopify Collabs Affiliate', 'https://orasamazingherbal.com/pages/affiliate', 'https://orasamazingherbal.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://orasamazingherbal.com/pages/affiliate', 'official_site', 'affiliate', 'Ora''s own Affiliate page states: ''Our affiliates start between 10-25% commission rate, based on platform, content quality and audience metrics'', average order range $50-60, custom assets on request, and routes creators to its Brand Ambassador program (free for qualified applicants, product for genuine content) or to ''Become an affiliate with Shopify Collabs to earn commission on your sales.'' Because the exact rate is assigned per creator from that range, commission_rate is recorded as null. The page''s separate 25% TikTok Shop showcase route was NOT used as this brand''s basis - its qualifying route is Shopify Collabs / its own ambassador program. The page publishes no earnings-cap statement, so commission_cap is recorded as unknown, never guessed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://orasamazingherbal.com/pages/affiliate', 'official_site', 'creator_saturation', 'No hard absolute creator count for Ora''s Amazing Herbal surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 13, 9, 8, 4, '{"niche_fit": "Herbal, eczema-care and tattoo-aftercare skincare from a family-run brand fits authentic problem/solution UGC.", "ugc_evidence": "Own ambassador program offering product for genuine content plus a Shopify Collabs affiliate route; no hard creator count published.", "compensation": "Published starting range of 10-25% assigned by platform and metrics is promising but not a settled single rate, so the rate is honestly null; cap unknown.", "contact_access": "Affiliate page invites questions to its community manager by email, though the address itself did not render in the fetched page text, so no email is recorded.", "opportunity_availability": "Ambassador applications and Collabs route are open; ambassador membership is free for qualified applicants.", "credibility": "Woman-owned, family-run brand publishing its Englewood, NJ address and phone on the page, founded on an eczema-care product for the founder''s daughter."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Care to Beauty', 'https://www.caretobeauty.com', 'Beauty retailer selling skincare and cosmetics across international stores, running its own creators affiliate program: apply on-site, get manually reviewed within 48 business hours, and earn commission on every confirmed order through custom product and category links.', null, 'published') returning id into bid;
