  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Care to Beauty Affiliate Program (Creators)', 'https://www.caretobeauty.com/us/creators/', 'https://www.caretobeauty.com/us/creators/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.caretobeauty.com/us/creators/', 'official_site', 'affiliate', 'Care to Beauty''s own USA creators page describes its affiliate program: ''No paperwork, no minimum following, no exclusivity. Just apply, share, earn!'' Applications are reviewed manually within 48 business hours; affiliates generate custom links for specific products, brands or categories, earn commission on every confirmed order, and cash out as in-store credit (no minimum) or bank transfer. Base rates are not published - the page says campaign boosts vary and ''You''ll always see the active rate next to each link in your dashboard'' - so commission_rate is recorded as null. The page publishes no earnings-cap statement, so commission_cap is recorded as unknown, never guessed. The program explicitly offers no gifted products or paid content, commission only.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.caretobeauty.com/us/creators/', 'official_site', 'creator_saturation', 'No hard absolute creator count for Care to Beauty surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 10, 10, 8, 4, '{"niche_fit": "A multi-brand beauty retailer lets creators monetize almost any skincare or makeup routine content through custom links.", "ugc_evidence": "Own creators program with custom link generation and a real-time earnings dashboard; explicitly commission-only with no gifting, and no hard creator count published.", "compensation": "Rates are only visible inside the dashboard and vary by campaign, so the rate is honestly null; cap unknown.", "contact_access": "On-site application form with manual review promised within 48 business hours; no public partnerships email on the page fetched.", "opportunity_availability": "Open application with no minimum following and no exclusivity.", "credibility": "Established international beauty retailer with stores in multiple countries and detailed published program terms."}'::jsonb);
