  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Saje Wellness Affiliate Program (ShareASale)', 'https://linkclicky.com/affiliate-program/saje-wellness/', 'https://linkclicky.com/affiliate-program/saje-wellness/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/saje-wellness/', 'affiliate_directory', 'affiliate', 'LinkClicky''s directory lists Saje Wellness on the ShareASale network at 10% per sale and describes the brand as natural skincare and beauty products connecting people with the healing power of plants. A second aggregator (Shopper) lists a 5-10% payout range instead, so the published rates conflict and commission_rate is recorded as null rather than settled. No earnings-cap statement was found on the pages fetched, so commission_cap is recorded as unknown, never guessed.', 'publicly_reported', now());
