  insert into public.brands (name, website, description, country, status) values ('RAMODO Jewelry', 'https://ramodo.net', 'Jewelry brand running the RAMODO Ambassador Program for fashion and jewelry creators. Ambassadors earn 10% commission on every referred sale, tracked through GOAFFPRO and UpPromote, and the program FAQ states there is no cap on how much an ambassador can earn.', null, 'published') returning id into bid;
