  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://RAMODO.NET/pages/ramodo-ambassador-program', 'official_program_page', 'affiliate_program', 'Official ambassador page: ''Earn a generous 10% commission on every successful sale made through your link''; the program is free to join and open to influencers with content focused on jewelry, fashion, or entrepreneurship.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://RAMODO.NET/pages/ramodo-ambassador-program', 'official_program_page', 'affiliate_program', 'Commission cap stated explicitly in the official FAQ: ''Is there a cap on how much I can earn? No! There is no cap on how much you can earn as a RAMODO Ambassador, making your earning potential limitless!''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://RAMODO.NET/pages/ramodo-ambassador-program', 'official_program_page', 'creator_program', 'Tracking runs through both GOAFFPRO and UpPromote with a 30-day referral window and a real-time dashboard; ambassadors receive high-resolution product images, banners and pre-written content ideas; support email support@ramodo.net is published on the page.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 16, 12, 9, 3, '{"niche_fit": "Jewelry is a staple fashion-creator category \u2014 pieces are worn on camera in GRWM, styling and review content.", "ugc_evidence": "The official page is built for influencers and content creators, supplies product images, banners and content ideas, and says ambassadors do not need a blog \u2014 social channels including Instagram, TikTok and YouTube qualify.", "compensation": "Flat 10% on every referred sale with an explicit no-cap statement in the official FAQ.", "contact_access": "Published ambassador support email (support@ramodo.net) on the official program page.", "opportunity_availability": "Open application on the brand''s own page; free to join, approval is selective but no follower minimum is published.", "credibility": "A small, little-known jewelry brand; the program runs on established platforms (GOAFFPRO, UpPromote) but the brand itself has limited public track record, so credibility stays low."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('House of Cortivo', 'https://www.houseofcortivo.com', 'Women''s wearable-art fashion brand founded by Hillary Cortivo — leggings and pieces built from original paintings, released in limited batches. Its own affiliate program pays 15% commission on every referred sale, paid monthly, with no cap and no follower requirement; currently open to US-based affiliates only.', null, 'published') returning id into bid;
