  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'House of Cortivo Affiliate Program', 'https://www.houseofcortivo.com/pages/affiliate-signup', 'https://www.houseofcortivo.com/pages/affiliate-signup', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.houseofcortivo.com/pages/affiliate-signup', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''15% Commission on every sale''; at the $80 legging example price each referred sale pays $12; commissions are paid monthly and affiliates get full visibility through an affiliate dashboard.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.houseofcortivo.com/pages/affiliate-signup', 'official_program_page', 'affiliate_program', 'Commission cap stated explicitly on the official page: ''No cap. No ceiling. The more you share, the more you earn'' and in the FAQ, ''paid monthly with no cap on what you can earn.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.houseofcortivo.com/pages/affiliate-signup', 'official_program_page', 'creator_program', 'No follower requirement and no monthly quota (''Whether you have 500 followers or 500K''); affiliates apply on the page and receive a unique link within 24 hours; sharing is welcomed on Instagram, TikTok, Pinterest, YouTube, blogs and email lists; US-based affiliates only for now.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 17, 6, 9, 3, '{"niche_fit": "Wearable-art leggings and fashion pieces are a natural try-on and styling fit for fashion and lifestyle creators.", "ugc_evidence": "The page is written directly to creators sharing on Instagram, TikTok, Pinterest and YouTube, with no follower minimum; it publishes no creator counts, so the score stays mid-range.", "compensation": "15% on every sale with explicit ''No cap. No ceiling.'' wording in both the earnings section and the FAQ.", "contact_access": "No direct partnerships email is published on the page; contact runs through the on-page application form.", "opportunity_availability": "Open application on the brand''s own page, link issued within 24 hours, no contract or minimum commitment; US-based affiliates only.", "credibility": "A very small founder-led brand (founder story names 17 years in luxury fashion including Chanel); limited public track record, so credibility stays low."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Blackland Watch Co.', 'https://blacklandwatchco.com', 'Watch retailer specialising in independent makers and new and pre-owned luxury timepieces. Its own affiliate program (portal on GoAffPro) pays 5% on watches sold for $150 or more and 1% below that, and its published rules state there is no commission cap per sale or on total earnings.', null, 'published') returning id into bid;
