  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'GoAffPro', 5, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://blacklandwatchco.com/pages/affiliate-program.', 'https://blacklandwatchco.goaffpro.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Blackland Watch Co. Affiliate Program', 'https://blacklandwatchco.com/pages/affiliate-program', 'https://blacklandwatchco.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://blacklandwatchco.com/pages/affiliate-program', 'official_program_page', 'affiliate_program', 'Official rate table: watches priced at $150 or more earn 5%, watches below $150 earn 1%, straps/cases/accessories earn no commission; new and pre-owned watches both qualify, including pre-owned luxury watches.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://blacklandwatchco.com/pages/affiliate-program', 'official_program_page', 'affiliate_program', 'Commission cap stated explicitly on the official page, twice: ''No commission cap. There is no maximum commission per eligible watch sale and no limit on your total affiliate earnings'' and ''There is no cap on commissions per sale or on an affiliate''s total earnings.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://blacklandwatchco.com/pages/affiliate-program', 'official_program_page', 'creator_program', 'The page invites watch enthusiasts, creators and podcasters; affiliates register through the brand''s GoAffPro portal (blacklandwatchco.goaffpro.com), are paid at least once per calendar month after the return period, and can contact the brand at info@blacklandwatchco.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 12, 11, 9, 3, '{"niche_fit": "Watches are a focused fashion-accessory niche \u2014 strong for watch and menswear creators, narrower for general fashion audiences.", "ugc_evidence": "The official page explicitly welcomes creators and podcasters, but publishes no creator counts or creator-specific perks beyond the referral link.", "compensation": "5% on watches at $150+ (1% below $150, nothing on accessories) \u2014 a low percentage, partly offset by high watch prices and an explicit no-cap statement in the program rules.", "contact_access": "Published contact email (info@blacklandwatchco.com) on the official program page.", "opportunity_availability": "Open registration through the brand''s own affiliate portal.", "credibility": "A small specialist retailer; the program rules are unusually detailed and transparent, but the brand has a limited public footprint, so credibility stays low."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cover Looks', 'https://coverlooks.com', 'Affordable, trend-led women''s fashion brand. Its own affiliate program gives fashion influencers, bloggers and content creators a referral link and a real-time earnings dashboard, pays monthly, and answers its earnings-limit question with ''There''s no cap on commissions''. The percentage rate itself is not published on the page, so the rate is recorded as null.', null, 'published') returning id into bid;
