  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cover Looks Affiliate Program', 'https://coverlooks.com/pages/register-affiliate-account', 'https://coverlooks.com/pages/register-affiliate-account', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://coverlooks.com/pages/register-affiliate-account', 'official_program_page', 'affiliate_program', 'Official page: the Cover Looks Affiliate Program ''allows you to earn commissions by promoting our stylish fashion collections'' and is aimed at fashion influencers, bloggers and content creators; affiliates get a unique referral link, exclusive promotional materials and real-time earnings tracking, paid monthly past a minimum threshold.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://coverlooks.com/pages/register-affiliate-account', 'official_program_page', 'affiliate_program', 'Commission cap stated explicitly on the official page: ''Is there a limit to how much I can earn? No! The more successful your promotions, the more you earn. There''s no cap on commissions, so the potential is limitless!''', 'verified', now());
