  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bauerfeind USA Affiliate Program', 'https://www.bauerfeind.us/affiliate-program/', 'https://www.bauerfeind.us/affiliate-program/', 'unverified', 'ugc');
