  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bauerfeind.us/affiliate-program/', 'official_program_page', 'creator_program', 'The program explicitly targets athletes, fitness and health content creators and bloggers; no website is required — blogs, newsletters, social media and YouTube channels are acceptable channels; affiliates must have a US-based audience.', 'verified', now());
