  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 13, 14, 8, 5, '{"niche_fit": "Braces and performance compression wear demo naturally in training, rehab and return-to-sport content \u2014 a strong fit for fitness creators.", "ugc_evidence": "The official page is written directly to athletes and fitness/health content creators, accepts social and YouTube channels without a website, and offers creator discount codes.", "compensation": "Rates start at 8% (the page does not publish the top of the range) and no cap statement is published, so the cap is honestly unknown.", "contact_access": "Dedicated affiliate email (affiliate@bauerfeindusa.com) published repeatedly on the official page.", "opportunity_availability": "Application on the brand''s own page after account creation; acceptance is reviewed and US audiences only.", "credibility": "The US arm of a leading global manufacturer of orthopedic braces and compression wear, with a published customer-service line and a 60-day money-back guarantee."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Craft Sportswear US', 'https://www.craftsports.us', 'US storefront of CRAFT, the Swedish high-performance endurance sportswear brand with a strong Nordic heritage. Its affiliate program runs through AvantLink and pays 10% commission to content publishers (5% for coupon/deal sites) with a 30-day cookie. No cap statement is published, so the cap is recorded as unknown.', 'United States', 'published') returning id into bid;
