  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.craftsports.us/pages/affiliate-program', 'official_program_page', 'affiliate_program', 'The program is run with AvantLink (''We''ve partnered with AvantLink, the leader in Affiliate Marketing technology''), which provides the affiliate tools free of charge; no commission-cap statement appears on the page, so commission_cap is recorded as unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 14, 5, 8, 5, '{"niche_fit": "High-performance endurance apparel (running, cycling, Nordic ski) is a natural gear-review and training-content fit for fitness creators.", "ugc_evidence": "Content publishers get the headline 10% rate, but the page speaks to websites and blogs generally and publishes no creator counts or creator-specific perks.", "compensation": "10% for content publishers (5% for coupon/deal sites) on a $100+ average order; no cap statement published, so the cap is honestly unknown.", "contact_access": "No direct partnerships email is published on the page; contact runs through the AvantLink application.", "opportunity_availability": "Open application via the brand''s own page into the AvantLink program.", "credibility": "An established global performance brand (''high performance, high endurance brand with a strong Nordic heritage'') running its program through AvantLink, a major network."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('AIVVIA Athletics', 'https://aivviaathletics.com', 'Women''s made-to-order activewear brand (''Made by women, for women''). Its Ambassador Program gives creators their own link and code, earned PR sets and early access, and states ''No caps'' on commission. The commission percentage itself is never published on the page, so the rate is recorded as null.', null, 'published') returning id into bid;
