  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'AIVVIA Athletics Ambassador Program', 'https://aivviaathletics.com/pages/apply', 'https://aivviaathletics.com/pages/apply', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aivviaathletics.com/pages/apply', 'official_program_page', 'creator_program', 'Official ambassador page: ''Your own link and code. Every order through you earns commission. No caps.'' Ambassadors also unlock earned PR sets, early access to drops, monthly perks and collab invites; applications are reviewed usually within 24 hours and activation follows within 24–48 hours.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aivviaathletics.com/pages/apply', 'official_program_page', 'creator_program', 'The program does not choose ambassadors by follower count (''We value authentic content, engagement, and real enthusiasm for the brand''); ambassadors must be 18 or older to earn commission; the page features named fitness-instructor and yoga-teacher ambassadors.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aivviaathletics.com/pages/apply', 'official_program_page', 'compensation', 'No commission percentage is published anywhere on the official page — the rate is provided only after acceptance — so commission_rate is recorded as null rather than guessed.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 10, 6, 9, 3, '{"niche_fit": "Women''s activewear sets across three compression fabrics are a core try-on and workout-content fit for fitness creators.", "ugc_evidence": "A creator-first ambassador program: no follower-count selection, named working fitness instructors as ambassadors, earned PR, early access and studio/instructor collaborations.", "compensation": "Explicit ''No caps'' wording on commission, but the percentage itself is unpublished, so compensation scores low until the rate is confirmed at acceptance.", "contact_access": "No email is published; contact runs through the on-page application form.", "opportunity_availability": "Open two-minute application on the brand''s own page with fast review; worldwide shipping where the brand ships.", "credibility": "A young, small made-to-order brand; the sustainability and made-to-order model is documented on the page, but the public track record is thin, so credibility stays low."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Click Fly', 'https://www.click-fly.com', 'Travel booking platform for flights, hotels, tours, transfers and holiday packages, operated from Tallinn, Estonia. Its own affiliate program is open to travel creators, bloggers and influencers with real-time tracking and dashboard payouts; joining is free with ''no limits on earning potential''. Commission values depend on volume and performance and are not published as percentages, so the rate is recorded as null.', 'Estonia', 'published') returning id into bid;
