  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.click-fly.com/page/affiliate-program', 'official_program_page', 'affiliate_program', 'Official page: affiliates ''earn strong commissions for every completed booking'' across flights, hotels, tours, car rentals/transfers, holiday packages and custom travel requests, with a real-time dashboard showing clicks, conversions, bookings and earnings.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.click-fly.com/page/affiliate-program', 'official_program_page', 'affiliate_program', 'Earnings-limit statement on the official page: joining is free with ''No membership fees, no hidden charges, and no limits on earning potential.''', 'verified', now());
