  insert into public.brands (name, website, description, country, status) values ('Sevenly Travel', 'https://www.sevenlytravel.com', 'Socially conscious online travel agency that turns hotel bookings into charitable giving. Its Sevenly Stars Creator Program is an affiliate initiative for travel influencers: commission on each completed hotel booking through a personalised link — including on the creator''s own trips — with ''No cap on earnings''. Payout percentages are not published on the page, so the rate is recorded as null.', null, 'published') returning id into bid;
