  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sevenlytravel.com/influencer', 'official_program_page', 'creator_program', 'Official page: the Sevenly Stars Program is an ''Exclusive affiliate initiative for influencers passionate about travel and social impact'' — creators apply, receive a unique booking link, share hotel deals and itineraries, and earn commission on each completed booking, including on their own trips.', 'verified', now());
