  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://vetster.com/en-ca/affiliates', 'official_site', 'affiliate', 'Official Vetster affiliate page fetched: ''No cost to sign up'', ''No cap on commission'', program managed by Impact Radius (Impact), application usually approved within 1 business day, brand assets and a unique promo code provided. ''Share & earn'' section: a fixed commission per appointment booked with the affiliate''s promo code, and ''There''s no cap on commissions, so share as much as you’d like across as many platforms as possible!'' — an explicit no-cap statement on the brand''s own page, so the commission cap is recorded as UNCAPPED. The official page does NOT publish the fixed per-appointment amount, so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliateslist.com/pet-affiliate-programs/', 'affiliate_directory', 'affiliate', 'Third-party listings conflict on the flat amount: The Affiliates List reports $15 per order via Impact with a 30-day cookie, while Lasso reports $30.00 per order for Vetster, Inc. Because the official page publishes no amount and third parties conflict ($15 vs $30), the rate is recorded as null rather than guessed.', 'publicly_reported', now());
