  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Innovet Pet Affiliate Program — 20-40% starting commission via Awin, 30-day cookie, $60 average order', 'https://www.innovetpet.com/pages/pet-affiliate-program', 'https://www.innovetpet.com/pages/pet-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.innovetpet.com/pages/pet-affiliate-program', 'official_site', 'affiliate', 'Official Innovet Pet affiliate page fetched: program run on Awin with a dedicated affiliate manager; ''We pay 20-40% starting commission rate per sale. Higher volume affiliates may be eligible for a higher commission rate''; average order value $60 (up to $24 commission at 40%); 30-day cookie; banners and exclusive coupons provided; real-time tracking through Awin. The FAQ restates ''We pay up to 40% starting commission rate per sale on average... Even our lowest starting commission at 20% per sale''. The published rate is a range set by the brand itself, so the starting rate of 20 is recorded. No cap statement appears anywhere on the fetched page, so the commission cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.innovetpet.com/pages/pet-affiliate-program', 'official_site', 'ugc_collab', 'The same page names ideal partners as bloggers, doggie daycares, dog walkers, dog trainers, veterinarians and animal lovers, accepts affiliates worldwide where Awin operates, charges no fees, and sets a $50 commission threshold before payout.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 20, 8, 9, 4, '{"niche_fit": "Pet health and CBD pet care are staple, demonstrable topics for pet UGC, with problem/solution products (mobility, skin, anxiety, blind-dog aids)", "ugc_evidence": "Official page explicitly recruits bloggers and pet-content partners and supplies banners, exclusive coupons and a dedicated affiliate manager", "compensation": "20-40% starting commission on the brand''s own page \u2014 among the highest published pet rates found; higher tiers for volume. No cap statement published, so cap is unknown", "contact_access": "Application runs through Awin; a dedicated affiliate manager is named on the page but no program email is published, so contact access is scored lower", "opportunity_availability": "Open application via Awin, free to join, affiliates accepted worldwide where Awin operates", "credibility": "Long-running specialist pet-health brand with named founder-pet product stories and a large published catalog"}'::jsonb);
