  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'A1 SolarStore Affiliate Program — 6% per sale (max $250 per order), no cap on total earnings, 90-day cookie, weekly payouts', 'https://a1solarstore.com/affiliate-program/', 'https://a1solarstore.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://a1solarstore.com/affiliate-program/', 'official_site', 'affiliate', 'Official A1 SolarStore affiliate page fetched: 6% commission on every qualified sale of solar panels, batteries, inverters, HVAC and home backup power; 90-day cookie; weekly Friday payouts with no minimum balance; 95% of transactions approved after verification (up to 7 days). The FAQ answers ''Is there a limit on how much I can earn?'' with ''No cap on your total earnings. The only limit is per order: commission maxes out at $250 on a single Catalog Products sale.'' — total earnings are explicitly uncapped on the brand''s own page, so the cap is recorded as UNCAPPED, with the $250 PER-ORDER ceiling documented here so it is not misread: a single large system sale cannot pay more than $250.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://a1solarstore.com/affiliate-program/', 'official_site', 'ugc_collab', 'The same page says the program is ''Built for 1,000+ partners'' and names creators & influencers (YouTube, Instagram, Facebook, TikTok and niche creators interested in solar, home upgrades and energy savings) as a core partner type, alongside publishers, communities and agencies; every partner gets a personal affiliate manager (contact details in the dashboard after sign-up). The 1,000+ partner figure is a partner count, not a creator count at the ~100 scale, so creator saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 18, 11, 9, 4, '{"niche_fit": "Home solar, batteries and backup power are high-ticket, highly demonstrable home-upgrade topics for home and tech UGC; average purchases run $566-$6,950 on the brand''s own table", "ugc_evidence": "Official page names YouTube/Instagram/TikTok creators as a core partner type and provides link builder, product feeds, widgets and promo codes", "compensation": "6% per sale with total earnings explicitly uncapped (''No cap on your total earnings''); per-order commission maxes at $250, which the high average order values regularly reach", "contact_access": "Direct program (no network layer) with a personal affiliate manager for every partner; manager contact appears in the dashboard after sign-up and a contact form is linked, but no program email is published", "opportunity_availability": "Open application, Ref ID and dashboard issued immediately at sign-up, review usually within 48 hours, free to join", "credibility": "Established US solar retailer with published verification/payout process and a 2025 growth award claim on its own page"}'::jsonb);
