  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/ruggable/', 'affiliate_directory', 'affiliate', 'UpPromote''s directory summary states Ruggable runs its program through established networks — CJ Affiliate, FlexOffers and Awin (non-US) — plus AspireIQ for influencer/creator management, with rates ''commonly cited as 3% to 6% per sale''. Other listings conflict further: LinkApprove reports up to 8% and WhichProgram lists up to 10% via ShareASale. Because published rates conflict (3-6% vs 6% vs up to 8% vs up to 10%) and no official program page publishing a rate was fetched, commission_rate is recorded as null. No cap statement was found, so the cap is unknown.', 'publicly_reported', now());
