  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://purpleorange.agency/case-studies/turning-up-the-heat-on-solo-stoves-affiliate-program-without-increasing-ad-spend/', 'industry_press', 'affiliate', 'Agency case study (Purple Orange, the brand''s affiliate management agency) reports Solo Stove''s program was reoriented around content partnerships and skilled creators/publishers, with Impact selected as the primary network partner, affiliate-driven revenue reaching about 11% of total company revenue, and coupon-site commissions reduced to 1% while content sites keep the full journey commission. No cap statement appears in either fetched source, so the cap is unknown.', 'publicly_reported', now());
