  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Eight Sleep Affiliate Program — smart sleep Pod via Impact; businesses contact bizdev@eightsleep.com (rate on application, see evidence)', 'https://www.eightsleep.com/ae/referral-terms-conditions/', 'https://www.eightsleep.com/ae/referral-terms-conditions/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.eightsleep.com/ae/referral-terms-conditions/', 'official_site', 'contact', 'Eight Sleep''s official referral terms page fetched: it distinguishes the individual referral program from the affiliate program and directs businesses interested in the Affiliate program to contact bizdev@eightsleep.com. The same page documents the referral program''s own caps (rewards in $100 increments, maximum 100 Qualified Referrals per calendar year) — those caps belong to the customer referral program, NOT the affiliate program, and are documented here so they are not misread as an affiliate cap; no affiliate cap statement was found, so the affiliate cap is unknown.', 'verified', now());
