  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 11, 10, 7, 4, '{"niche_fit": "Sleep tech is a strong tech-meets-home UGC niche \u2014 temperature control and sleep tracking demo well for biohacking, recovery and smart-home audiences", "ugc_evidence": "The affiliate route is aimed at businesses and publishers (the official page separates it from the individual referral program); premium hardware supports long-form review content", "compensation": "Published rates conflict (2% to up to 10%) and the official affiliate rate is unpublished, so the rate is null; premium $1,500+ price points lift per-sale value even at low percentages", "contact_access": "Official page publishes bizdev@eightsleep.com specifically for affiliate-program interest", "opportunity_availability": "Application through Impact / business contact; less self-serve than the other programs in this group, so availability is scored lower", "credibility": "Well-known, heavily covered sleep-tech brand with premium retail presence"}'::jsonb);
